<?php
declare(strict_types=1); require __DIR__ . '/config.php';
if (isset($_GET['logout'])) { session_unset(); session_destroy(); header('Location:index.php'); exit; }
$categories=db()->query('SELECT * FROM categories ORDER BY sort_order,title')->fetchAll(); $slug=trim($_GET['category']??''); $query=trim($_GET['q']??''); $params=[];$where=['p.is_active=1']; if($slug!==''){$where[]='c.slug=:slug';$params['slug']=$slug;}if($query!==''){$where[]='p.title LIKE :q';$params['q']='%'.$query.'%';}$s=db()->prepare('SELECT p.*,c.title category_title,c.slug FROM playlists p JOIN categories c ON c.id=p.category_id WHERE '.implode(' AND ',$where).' ORDER BY p.id DESC');$s->execute($params);$playlists=$s->fetchAll();
function icon(string $name): string { $paths=['menu'=>'M4 7h16M4 12h16M4 17h16','settings'=>'M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7Zm0-13v2m0 15v2m9.5-9.5h-2M4.5 12h-2m16.2-6.7-1.4 1.4M6.7 17.3l-1.4 1.4m0-13.4 1.4 1.4m12 10.6 1.4 1.4','bell'=>'M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9Zm-8 12h4','user'=>'M20 21a8 8 0 0 0-16 0m8-10a4 4 0 1 0 0-8 4 4 0 0 0 0 8'];return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'.$paths[$name].'"/></svg>';}
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BOMBALA — IPTV</title><link rel="stylesheet" href="styles.css"></head><body><header class="topbar"><a class="logo" href="index.php"><img src="assets/bombala-logo.png" alt="BOMBALA"></a><div class="head-space"></div><button class="header-icon" aria-label="Меню"><?=icon('menu')?></button><a class="header-icon" href="profile.php" aria-label="Настройки"><?=icon('settings')?></a><button class="header-icon" aria-label="Уведомления"><?=icon('bell')?></button><?php if(isLoggedIn()): ?><a class="profile-chip" href="profile.php"><?=icon('user')?><span>Профиль</span></a><?php else: ?><a class="login" href="auth.php">Войти</a><?php endif; ?><button class="header-icon" aria-label="Меню"><?=icon('menu')?></button></header><main class="catalog" id="catalog"><div class="catalog-heading"><p class="eyebrow">IPTV БИБЛИОТЕКА</p><h1>Плейлисты</h1><p>Подберите телевидение, спорт, кино и детские каналы.</p></div><form class="search"><input name="q" value="<?=e($query)?>" placeholder="Поиск плейлистов..."><button>Поиск</button></form><div class="categories"><a class="<?=$slug===''?'active':''?>" href="index.php">Все</a><?php foreach($categories as $c):?><a class="<?=$slug===$c['slug']?'active':''?>" href="?category=<?=urlencode($c['slug'])?>"><?=e($c['title'])?></a><?php endforeach;?></div><p class="found"><?=count($playlists)?> плейлистов</p><div class="grid"><?php foreach($playlists as $p):?><article class="card"><div class="cover" style="--cover:<?=e($p['cover_color'])?>"><span><?=e($p['quality'])?></span><b><?=e($p['category_title'])?></b></div><div class="card-body"><small><?= (int)$p['channels']?> каналов · обновлено сегодня</small><h2><?=e($p['title'])?></h2><p><?=e($p['description']??'')?></p><?php if(isLoggedIn()):?><a class="get-link" href="playlist.php?id=<?=(int)$p['id']?>">Открыть плейлист <i>→</i></a><?php else:?><a class="locked" href="auth.php">Доступ после входа <i>→</i></a><?php endif;?></div></article><?php endforeach;?></div></main></body></html>
